"""Standalone local review; no API and no web dependencies."""
import json
from pathlib import Path
HERE=Path(__file__).resolve().parent
load=lambda n:json.loads((HERE/n).read_text(encoding='utf-8'))
summary=load('summary.json');bank=load('questions.en.json');audit={r['id']:r for r in load('audit.json')['records']};uk={r['id']:r for r in load('translations.uk.json')['questions']}
rows=[dict(id=q['id'],category=q['category'],text=q['text'],choices=q['choices'],correct=q['correct'],tags=[t.removeprefix('custom:semantic:') for t in q['tags'] if t.startswith('custom:semantic:')],uk=uk.get(q['id']),notes=audit[q['id']]['notes']+(['Content review added an evidence-backed topic; original model notes retained below.'] if audit[q['id']].get('reviewerAdditions') else []),proposals=audit[q['id']]['proposals'],eu='EU:en' in q['tags'],fun='custom:fun-bank:candidate' in q['tags']) for q in bank]
payload=json.dumps(rows,ensure_ascii=False,separators=(',',':')).replace('<','\u003c')
page=r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Luna balanced bank · TriviTV</title><style>body{margin:0;background:#f3f6f3;color:#243c3b;font:16px/1.5 system-ui}main{max-width:1300px;margin:auto;padding:24px}header,article{background:white;border:1px solid #d7e2df;border-radius:12px;padding:22px;margin:0 0 18px}h1,h2,h3{margin:0 0 8px}h2{font-size:20px}small{display:block;color:#6a7977}.bilingual{display:grid;grid-template-columns:1fr 1fr;gap:24px}.choices{display:grid;gap:5px}.choices div{border:1px solid #dde5e3;border-radius:5px;padding:6px 10px}.choices .correct{background:#e4f2e9;border-color:#acd1b8}.tags{display:flex;flex-wrap:wrap;gap:5px;margin-top:16px}.tags span{background:#ecf1f6;color:#364e6c;border-radius:5px;padding:3px 8px;font-size:13px}.notes{color:#865d25}a{color:#19746e}.filters{display:flex;flex-wrap:wrap;gap:12px;margin-top:16px}input,select,button{font:inherit;padding:8px 12px;border:1px solid #bfcfcb;border-radius:6px;background:#fff;color:inherit}input{min-width:250px}button{cursor:pointer}button:disabled{opacity:.45}.pager{display:flex;align-items:center;gap:14px;margin:16px 0}.status{font-size:14px;color:#637774}@media(max-width:750px){main{padding:10px}.bilingual{grid-template-columns:1fr}header,article{padding:16px}input{min-width:0;width:100%}}</style><main><header><h1>Luna · balanced classification bank</h1><p id="summary"></p><p><a href="questions.en.json">Full English JSON</a> · <a href="questions.en.csv">Bilingual CSV</a> · <a href="questions.eu-en.json">EU English</a> · <a href="questions.fun-en.json">Fun English</a> · <a href="questions.fun-uk.json">Fun Ukrainian</a> · <a href="REPORT.md">Run report</a></p><p>125 shuffled questions from each of 20 source categories. English master content and Ukrainian drafts are linked by original ID. Machine tags are unreviewed; uncertain proposals are withheld. Existing human tags take priority. Green answer markers reproduce source keys; they do not certify factual accuracy.</p><p class="status">All-category export retains religion/US-specific content in Main. EU and Fun filters below use existing eligibility; classification did not change it.</p><div class="filters"><select id="category" aria-label="Category"><option value="">All categories</option></select><select id="pool" aria-label="Pool"><option value="">All selected</option><option value="eu">Existing EU English candidates</option><option value="fun">Existing Fun English candidates</option><option value="notes">With review notes or proposals</option></select><input id="search" aria-label="Search" placeholder="Search questions, IDs or tags"></div></header><div class="pager"><button id="prev">← Previous</button><span id="count"></span><button id="next">Next →</button></div><div id="cards"></div><div class="pager"><button id="prev-bottom">← Previous</button><span id="count-bottom"></span><button id="next-bottom">Next →</button></div></main><script type="application/json" id="data">__DATA__</script><script>
const rows=JSON.parse(document.querySelector('#data').textContent),summary=__SUMMARY__,el=id=>document.getElementById(id),esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let page=0;
el('summary').textContent=`${summary.questions.toLocaleString()} questions · ${summary.linkedUkrainianDrafts.toLocaleString()} linked Ukrainian drafts · $${summary.usageCostUsd.toFixed(4)} token cost of $5 ceiling`;
for(const c of Object.keys(summary.perCategory)){const option=document.createElement('option');option.value=c;option.textContent=c+' (125)';el('category').append(option)}
function choices(q,correct){return '<div class="choices">'+q.choices.map((v,i)=>`<div class="${i===correct?'correct':''}">${'ABCD'[i]}. ${esc(v)}${i===correct?' ✓':''}</div>`).join('')+'</div>'}
function render(){const term=el('search').value.toLowerCase(),cat=el('category').value,pool=el('pool').value,filtered=rows.filter(q=>(!cat||q.category===cat)&&(!pool||(pool==='notes'?q.notes.length||q.proposals.length:q[pool]))&&(!term||JSON.stringify(q).toLowerCase().includes(term)));page=Math.min(page,Math.max(0,Math.ceil(filtered.length/50)-1));const shown=filtered.slice(page*50,page*50+50);el('count').textContent=el('count-bottom').textContent=`${filtered.length? page*50+1:0}–${Math.min(filtered.length,page*50+50)} of ${filtered.length}`;for(const id of ['prev','prev-bottom'])el(id).disabled=page===0;for(const id of ['next','next-bottom'])el(id).disabled=(page+1)*50>=filtered.length;el('cards').innerHTML=shown.map(q=>`<article><h2>${esc(q.category)}</h2><a href="http://127.0.0.1:8791/?question=${encodeURIComponent(q.id)}">${esc(q.id)}</a><small>${q.eu?'EU English candidate':'Outside existing EU English candidates'} · ${q.fun?'Fun candidate':'Outside existing Fun candidates'}</small><div class="bilingual"><section><h3>English</h3><p>${esc(q.text)}</p>${choices(q,q.correct)}</section><section><h3>Українська · draft</h3><p>${esc(q.uk?.text||'No linked Ukrainian draft')}</p>${q.uk?choices(q.uk,q.correct):''}</section></div><div class="tags">${q.tags.map(t=>`<span>${esc(t)}</span>`).join('')}</div>${q.notes.length?'<ul class="notes">'+q.notes.map(n=>`<li>${esc(n)}</li>`).join('')+'</ul>':''}${q.proposals.length?`<details><summary>${q.proposals.length} unpublished proposals</summary><ul>${q.proposals.map(p=>`<li>${esc(p.tag)} — ${esc(p.reason)}</li>`).join('')}</ul></details>`:''}</article>`).join('')||'<p>No matching questions.</p>'}
for(const id of ['search','category','pool'])el(id).addEventListener(id==='search'?'input':'change',()=>{page=0;render()});for(const id of ['prev','prev-bottom'])el(id).onclick=()=>{page--;render();window.scrollTo(0,0)};for(const id of ['next','next-bottom'])el(id).onclick=()=>{page++;render();window.scrollTo(0,0)};render();
</script></html>'''
# Prevent data from terminating its inert script element.
page=page.replace('__DATA__',json.dumps(rows,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c')).replace('__SUMMARY__',json.dumps(summary,ensure_ascii=False).replace('<','\\u003c'))
(HERE/'review.html').write_text(page,encoding='utf-8')
print('Rendered standalone review: '+str(len(rows))+' questions')
